```js
const assert = require("node:assert/strict");

// Basic runs
assert.deepStrictEqual(groupRuns([]), []);
assert.deepStrictEqual(groupRuns([1]), [{ value: 1, count: 1 }]);
assert.deepStrictEqual(
  groupRuns([1, 1, 2, 2, 2, -3, 0, 0]),
  [
    { value: 1, count: 2 },
    { value: 2, count: 3 },
    { value: -3, count: 1 },
    { value: 0, count: 2 },
  ]
);

// Non-mutation
const input = [5, 5, 6, 6, 6];
const before = input.slice();
const result = groupRuns(input);

assert.deepStrictEqual(result, [
  { value: 5, count: 2 },
  { value: 6, count: 3 },
]);
assert.deepStrictEqual(input, before);

// Non-array inputs
for (const bad of [null, undefined, {}, "1,1", 42, new Int32Array([1, 1])]) {
  assert.throws(() => groupRuns(bad), TypeError);
}

// Non-integer elements
for (const bad of [
  [1, 2.5],
  [1, "2"],
  [1, NaN],
  [1, Infinity],
  [1, undefined],
  [1, null],
  [1, 1n],
  [1, {}],
]) {
  assert.throws(() => groupRuns(bad), TypeError);
}

// Empty array slots / sparse arrays
const sparse = [1, , 3];
assert.throws(() => groupRuns(sparse), TypeError);

const allHoles = new Array(2);
assert.throws(() => groupRuns(allHoles), TypeError);

console.log("All assertions passed");
```

An empty array is accepted and returns `[]`; sparse array slots are rejected with `TypeError`.

